import React, { useEffect, useRef, useState } from 'react';
import * as powerbi from 'powerbi-client';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import 'leaflet.heat';
import 'tailwindcss'

// Fix for default markers in Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const Analytics = () => {
  const reportRef = useRef(null);
  const mapRef = useRef(null);
  const mapInstance = useRef(null);
  const [mode, setMode] = useState("demo");
  const [embedFailed, setEmbedFailed] = useState(false);
  const [timeRange, setTimeRange] = useState("monthly");
  const [activeTab, setActiveTab] = useState("overview");
  const [isLoading, setIsLoading] = useState(true);
  const [selectedDistrict, setSelectedDistrict] = useState("All Districts");
  const [showFilters, setShowFilters] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [locationAccess, setLocationAccess] = useState(false);
  const [heatmapData, setHeatmapData] = useState([]);
  const [predictiveData, setPredictiveData] = useState(null);

  // Simulated data for demo mode
  const demoData = {
    visitorsByDistrict: [
      { district: "Ranchi", visitors: 12500, growth: 12, lat: 23.3441, lng: 85.3096 },
      { district: "Jamshedpur", visitors: 9800, growth: 8, lat: 22.8046, lng: 86.2029 },
      { district: "Dhanbad", visitors: 8700, growth: 5, lat: 23.7957, lng: 86.4304 },
      { district: "Bokaro", visitors: 6500, growth: 15, lat: 23.6693, lng: 86.1511 },
      { district: "Hazaribagh", visitors: 5200, growth: -2, lat: 23.9924, lng: 85.3616 },
      { district: "Deoghar", visitors: 7800, growth: 20, lat: 24.4823, lng: 86.7007 },
    ],
    revenueTrends: {
      labels: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
      data: [45, 52, 49, 60, 70, 85, 95, 90, 78, 82, 88, 105]
    },
    categoryPerformance: [
      { category: "Adventure", revenue: 42, trend: "up" },
      { category: "Cultural", revenue: 35, trend: "up" },
      { category: "Pilgrimage", revenue: 28, trend: "stable" },
      { category: "Wildlife", revenue: 22, trend: "down" },
    ],
    demographicData: {
      ageGroups: [
        { group: "18-25", percentage: 25 },
        { group: "26-35", percentage: 35 },
        { group: "36-45", percentage: 22 },
        { group: "46-55", percentage: 12 },
        { group: "56+", percentage: 6 },
      ],
      sources: [
        { source: "Direct", percentage: 30 },
        { source: "Online Travel Agencies", percentage: 40 },
        { source: "Social Media", percentage: 15 },
        { source: "Referrals", percentage: 10 },
        { source: "Other", percentage: 5 },
      ]
    },
    // New data for advanced features
    realTimeVisitors: [
      { id: 1, location: "Ranchi", time: "2 mins ago", activity: "Viewing waterfalls" },
      { id: 2, location: "Jamshedpur", time: "5 mins ago", activity: "Zoo visit" },
      { id: 3, location: "Deoghar", time: "7 mins ago", activity: "Temple visit" },
      { id: 4, location: "Netarhat", time: "10 mins ago", activity: "Sunset point" },
    ],
    predictiveInsights: {
      nextMonthVisitors: 54300,
      recommendedFocus: "Adventure tourism",
      expectedGrowth: 15.2,
      peakPeriod: "November-December"
    }
  };

  const REPORT_ID = process.env.REACT_APP_REPORT_ID;
  const GROUP_ID = process.env.REACT_APP_GROUP_ID;
  const ACCESS_TOKEN = process.env.REACT_APP_ACCESS_TOKEN;

  // Initialize map
  useEffect(() => {
    if (activeTab === "geospatial" && mapRef.current && !mapInstance.current) {
      // Wait for the next tick to ensure DOM is ready
      setTimeout(() => {
        initializeMap();
      }, 0);
    }
    
    // Clean up map when component unmounts or tab changes away from geospatial
    return () => {
      if (mapInstance.current && activeTab !== "geospatial") {
        mapInstance.current.remove();
        mapInstance.current = null;
      }
    };
  }, [activeTab]);

  // Get user location
  useEffect(() => {
    if (navigator.geolocation && activeTab === "geospatial") {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const location = {
            lat: position.coords.latitude,
            lng: position.coords.longitude
          };
          setUserLocation(location);
          setLocationAccess(true);
          
          // If map exists, add user location marker
          if (mapInstance.current) {
            L.marker([location.lat, location.lng])
              .addTo(mapInstance.current)
              .bindPopup('Your Location')
              .openPopup();
          }
        },
        (error) => {
          console.log("Geolocation access denied or unavailable");
          setLocationAccess(false);
        }
      );
    }
  }, [activeTab]);

  // Generate heatmap data
  useEffect(() => {
    const heatmapPoints = [];
    demoData.visitorsByDistrict.forEach(district => {
      // Generate multiple points around each district to simulate visitor density
      for (let i = 0; i < district.visitors / 100; i++) {
        heatmapPoints.push([
          district.lat + (Math.random() - 0.5) * 0.2,
          district.lng + (Math.random() - 0.5) * 0.2,
          Math.random() * 0.8 + 0.2 // Intensity between 0.2 and 1.0
        ]);
      }
    });
    setHeatmapData(heatmapPoints);
    setPredictiveData(demoData.predictiveInsights);
  }, []);

  const initializeMap = () => {
    // Ensure the map container has height
    if (mapRef.current) {
      mapRef.current.style.height = '384px';
    }
    
    // Initialize Leaflet map
    const map = L.map(mapRef.current).setView([23.6345, 85.3803], 8);
    mapInstance.current = map;
    
    // Add tile layer
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
    }).addTo(map);
    
    // Add markers for each district
    demoData.visitorsByDistrict.forEach(district => {
      L.marker([district.lat, district.lng])
        .addTo(map)
        .bindPopup(`
          <b>${district.district}</b><br>
          Visitors: ${district.visitors.toLocaleString()}<br>
          Growth: ${district.growth}%
        `);
    });
    
    // Add heatmap layer if heatmapData is available
    if (heatmapData.length > 0) {
      L.heatLayer(heatmapData, {
        radius: 25,
        blur: 15,
        maxZoom: 17,
        gradient: {0.4: 'blue', 0.65: 'lime', 1: 'red'}
      }).addTo(map);
    }
    
    // Add user location if available
    if (userLocation) {
      L.marker([userLocation.lat, userLocation.lng])
        .addTo(map)
        .bindPopup('Your Location')
        .openPopup();
    }
    
    // Force a resize to ensure map renders correctly
    setTimeout(() => {
      map.invalidateSize();
    }, 100);
  };

  useEffect(() => {
    if (mode !== "live") {
      // Simulate loading for demo mode
      setTimeout(() => setIsLoading(false), 1500);
      return;
    }

    if (!REPORT_ID || !GROUP_ID || !ACCESS_TOKEN) {
      console.warn("Missing Power BI credentials. Switching to dry demo.");
      setEmbedFailed(true);
      setMode("demo");
      return;
    }

    setIsLoading(true);

    const embedConfig = {
      type: "report",
      id: REPORT_ID,
      embedUrl: `https://app.powerbi.com/reportEmbed?reportId=${REPORT_ID}&groupId=${GROUP_ID}`,
      accessToken: ACCESS_TOKEN,
      tokenType: powerbi.models.TokenType.Embed,
      settings: {
        filterPaneEnabled: false,
        navContentPaneEnabled: true,
        layoutType: powerbi.models.LayoutType.Custom,
        customLayout: {
          displayOption: powerbi.models.DisplayOption.FitToPage,
        },
      },
    };

    try {
      const powerbiService = new powerbi.service.Service(
        powerbi.factories.hpmFactory,
        powerbi.factories.wpmpFactory,
        powerbi.factories.routerFactory
      );

      powerbiService.reset(reportRef.current);
      const report = powerbiService.embed(reportRef.current, embedConfig);
      
      report.on("loaded", () => {
        setIsLoading(false);
      });
      
      report.on("error", () => {
        setEmbedFailed(true);
        setIsLoading(false);
      });
    } catch (error) {
      console.error("Power BI embedding failed:", error);
      setEmbedFailed(true);
      setMode("demo");
      setIsLoading(false);
    }
  }, [mode]);

  // Function to render bar chart for visitors by district
  const renderVisitorsBarChart = () => {
    const maxVisitors = Math.max(...demoData.visitorsByDistrict.map(item => item.visitors));
    
    return (
      <div className="h-64 flex items-end space-x-4 pt-4">
        {demoData.visitorsByDistrict.map((item, index) => (
          <div key={index} className="flex flex-col items-center flex-1">
            <div className="relative flex flex-col items-center group">
              <div 
                className="bg-gradient-to-t from-blue-400 to-blue-600 w-full rounded-t-md transition-all duration-300 hover:from-blue-300 hover:to-blue-500"
                style={{ height: `${(item.visitors / maxVisitors) * 100}%`, minHeight: '10px' }}
              ></div>
              <div className="text-xs mt-1 text-gray-600 truncate w-full text-center">{item.district}</div>
              <div className="absolute -top-8 hidden group-hover:block bg-gray-800 text-white text-xs py-1 px-2 rounded-md z-10">
                {item.visitors.toLocaleString()} visitors
                <div className={`text-xs ${item.growth >= 0 ? 'text-green-300' : 'text-red-300'}`}>
                  {item.growth >= 0 ? '↑' : '↓'} {Math.abs(item.growth)}%
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    );
  };

  // Function to render revenue trends chart
  const renderRevenueChart = () => {
    const maxRevenue = Math.max(...demoData.revenueTrends.data);
    
    return (
      <div className="h-64 flex items-end space-x-1 pt-4">
        {demoData.revenueTrends.data.map((value, index) => (
          <div key={index} className="flex flex-col items-center flex-1">
            <div 
              className="bg-gradient-to-t from-green-400 to-green-600 w-full rounded-t-md"
              style={{ height: `${(value / maxRevenue) * 100}%` }}
            ></div>
            <div className="text-xs mt-1 text-gray-600">{demoData.revenueTrends.labels[index]}</div>
          </div>
        ))}
      </div>
    );
  };

  // Function to render demographic charts
  const renderDemographicCharts = () => {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <h4 className="font-bold mb-4 text-center">Age Groups</h4>
          <div className="flex flex-col space-y-3">
            {demoData.demographicData.ageGroups.map((item, index) => (
              <div key={index} className="flex items-center">
                <div className="w-16 text-sm">{item.group}</div>
                <div className="flex-1 bg-gray-200 rounded-full h-4">
                  <div 
                    className="bg-gradient-to-r from-purple-400 to-purple-600 h-4 rounded-full" 
                    style={{ width: `${item.percentage}%` }}
                  ></div>
                </div>
                <div className="w-12 text-right text-sm font-medium">{item.percentage}%</div>
              </div>
            ))}
          </div>
        </div>
        
        <div>
          <h4 className="font-bold mb-4 text-center">Visitor Sources</h4>
          <div className="flex flex-col space-y-3">
            {demoData.demographicData.sources.map((item, index) => (
              <div key={index} className="flex items-center">
                <div className="w-40 text-sm">{item.source}</div>
                <div className="flex-1 bg-gray-200 rounded-full h-4">
                  <div 
                    className="bg-gradient-to-r from-orange-400 to-orange-600 h-4 rounded-full" 
                    style={{ width: `${item.percentage}%` }}
                  ></div>
                </div>
                <div className="w-12 text-right text-sm font-medium">{item.percentage}%</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  // Function to render category performance
  const renderCategoryPerformance = () => {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {demoData.categoryPerformance.map((item, index) => (
          <div key={index} className="bg-gradient-to-br from-white to-gray-50 p-4 rounded-lg shadow border border-gray-100">
            <h4 className="font-bold text-gray-700">{item.category}</h4>
            <div className="flex items-baseline mt-2">
              <span className="text-2xl font-bold text-gray-800">${item.revenue}</span>
              <span className="text-sm text-gray-500 ml-1">million</span>
            </div>
            <div className={`flex items-center mt-2 text-sm ${item.trend === 'up' ? 'text-green-600' : item.trend === 'down' ? 'text-red-600' : 'text-yellow-600'}`}>
              {item.trend === 'up' ? '↗' : item.trend === 'down' ? '↘' : '→'} 
              <span className="ml-1">{item.trend === 'up' ? 'Increasing' : item.trend === 'down' ? 'Decreasing' : 'Stable'}</span>
            </div>
          </div>
        ))}
      </div>
    );
  };

  // Function to render real-time visitors
  const renderRealTimeVisitors = () => {
    return (
      <div className="space-y-4">
        {demoData.realTimeVisitors.map(visitor => (
          <div key={visitor.id} className="flex items-center p-3 bg-gray-50 rounded-lg">
            <div className="bg-blue-100 p-2 rounded-full mr-3">
              <span className="text-blue-600">👤</span>
            </div>
            <div className="flex-1">
              <p className="font-medium">{visitor.location}</p>
              <p className="text-sm text-gray-600">{visitor.activity}</p>
            </div>
            <div className="text-sm text-gray-500">{visitor.time}</div>
          </div>
        ))}
      </div>
    );
  };

  // Function to render predictive insights
  const renderPredictiveInsights = () => {
    if (!predictiveData) return null;
    
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 p-6 rounded-lg">
          <h4 className="font-bold text-lg mb-4">Next Month Forecast</h4>
          <div className="text-3xl font-bold text-indigo-800">{predictiveData.nextMonthVisitors.toLocaleString()}</div>
          <p className="text-gray-600 mt-2">Expected Visitors</p>
          <div className="mt-4 flex items-center text-green-600">
            <span className="text-xl">↑</span>
            <span className="ml-1 font-medium">{predictiveData.expectedGrowth}% growth</span>
          </div>
        </div>
        
        <div className="bg-gradient-to-br from-green-50 to-teal-50 p-6 rounded-lg">
          <h4 className="font-bold text-lg mb-4">Recommendation</h4>
          <p className="text-teal-800 font-medium text-lg">{predictiveData.recommendedFocus}</p>
          <p className="text-gray-600 mt-2">Should be your focus area for maximum ROI</p>
          <div className="mt-4">
            <p className="text-sm text-gray-600">Peak period: <span className="font-medium">{predictiveData.peakPeriod}</span></p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="analytics-dashboard bg-gray-50 min-h-screen">
      <style>
        {`
          .leaflet-container {
            height: 100%;
            width: 100%;
            z-index: 1;
          }
          .h-64 {
            min-height: 16rem;
          }
          .z-10 {
            z-index: 10;
          }
        `}
      </style>
      
      <div className="bg-white shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center px-6 py-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center">
              <span className="bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg p-2 mr-3">📊</span>
              Jharkhand Tourism Analytics Dashboard
            </h2>
            <p className="text-gray-600 mt-1">Data-driven insights for tourism management</p>
          </div>
          
          <div className="flex flex-wrap gap-2 mt-4 md:mt-0">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-50"
            >
              <span className="mr-2">🔍</span> Filters
            </button>
            
            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg"
            >
              <option value="weekly">Weekly</option>
              <option value="monthly">Monthly</option>
              <option value="quarterly">Quarterly</option>
              <option value="yearly">Yearly</option>
            </select>
            
            <button
              onClick={() => setMode(mode === "live" ? "demo" : "live")}
              className={`px-4 py-2 rounded-lg flex items-center ${mode === "live" ? "bg-gradient-to-r from-blue-600 to-blue-800 text-white" : "bg-gradient-to-r from-gray-600 to-gray-800 text-white"}`}
            >
              <span className="mr-2">{mode === "live" ? "🔴" : "⚪"}</span>
              {mode === "live" ? "Live View" : "Demo Mode"}
            </button>
          </div>
        </div>

        {/* Filters Panel */}
        {showFilters && (
          <div className="px-6 py-4 bg-gray-50 border-t border-gray-200">
            <div className="flex flex-wrap gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">District</label>
                <select
                  value={selectedDistrict}
                  onChange={(e) => setSelectedDistrict(e.target.value)}
                  className="bg-white border border-gray-300 text-gray-700 px-3 py-2 rounded-lg text-sm"
                >
                  <option value="All Districts">All Districts</option>
                  {demoData.visitorsByDistrict.map((district, index) => (
                    <option key={index} value={district.district}>{district.district}</option>
                  ))}
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                <select className="bg-white border border-gray-300 text-gray-700 px-3 py-2 rounded-lg text-sm">
                  <option value="all">All Categories</option>
                  <option value="adventure">Adventure</option>
                  <option value="cultural">Cultural</option>
                  <option value="pilgrimage">Pilgrimage</option>
                  <option value="wildlife">Wildlife</option>
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date Range</label>
                <select className="bg-white border border-gray-300 text-gray-700 px-3 py-2 rounded-lg text-sm">
                  <option value="7">Last 7 days</option>
                  <option value="30">Last 30 days</option>
                  <option value="90">Last 90 days</option>
                  <option value="365">Last year</option>
                </select>
              </div>
              
              <div className="flex items-end">
                <button className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-blue-700">
                  Apply Filters
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Navigation Tabs */}
        <div className="px-6 border-t border-gray-200">
          <nav className="flex space-x-8 overflow-x-auto">
            {["overview", "visitors", "revenue", "demographics", "geospatial", "realtime", "predictive", "feedback"].map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`py-4 px-1 font-medium text-sm border-b-2 whitespace-nowrap ${activeTab === tab ? "border-blue-500 text-blue-600" : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"}`}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)}
              </button>
            ))}
          </nav>
        </div>
      </div>

      {/* Main Content */}
      <div className="p-6">
        {isLoading ? (
          <div className="flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
              <p className="text-gray-600">Loading dashboard data...</p>
            </div>
          </div>
        ) : mode === "live" && !embedFailed ? (
          <div ref={reportRef} className="report-container h-[70vh] border rounded-lg shadow bg-white" />
        ) : (
          <div className="space-y-6">
            {/* Overview Tab */}
            {activeTab === "overview" && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <div className="flex items-center">
                      <div className="bg-blue-100 p-3 rounded-lg">
                        <span className="text-blue-600 text-xl">👥</span>
                      </div>
                      <div className="ml-4">
                        <p className="text-gray-600">Total Visitors</p>
                        <h3 className="text-2xl font-bold text-gray-800">49,500</h3>
                        <p className="text-green-600 text-sm flex items-center">
                          <span>↑ 12.5%</span> from last month
                        </p>
                      </div>
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <div className="flex items-center">
                      <div className="bg-green-100 p-3 rounded-lg">
                        <span className="text-green-600 text-xl">💰</span>
                      </div>
                      <div className="ml-4">
                        <p className="text-gray-600">Total Revenue</p>
                        <h3 className="text-2xl font-bold text-gray-800">$232M</h3>
                        <p className="text-green-600 text-sm flex items-center">
                          <span>↑ 8.2%</span> from last month
                        </p>
                      </div>
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <div className="flex items-center">
                      <div className="bg-purple-100 p-3 rounded-lg">
                        <span className="text-purple-600 text-xl">📅</span>
                      </div>
                      <div className="ml-4">
                        <p className="text-gray-600">Avg. Stay Duration</p>
                        <h3 className="text-2xl font-bold text-gray-800">3.2 days</h3>
                        <p className="text-red-600 text-sm flex items-center">
                          <span>↓ 0.3 days</span> from last month
                        </p>
                      </div>
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <div className="flex items-center">
                      <div className="bg-orange-100 p-3 rounded-lg">
                        <span className="text-orange-600 text-xl">⭐</span>
                      </div>
                      <div className="ml-4">
                        <p className="text-gray-600">Satisfaction Rate</p>
                        <h3 className="text-2xl font-bold text-gray-800">94%</h3>
                        <p className="text-green-600 text-sm flex items-center">
                          <span>↑ 2%</span> from last month
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
                
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4 flex items-center">
                      <span className="mr-2">📈</span> Visitors by District
                    </h3>
                    {renderVisitorsBarChart()}
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4 flex items-center">
                      <span className="mr-2">💹</span> Revenue Trends ({timeRange})
                    </h3>
                    {renderRevenueChart()}
                  </div>
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4 flex items-center">
                    <span className="mr-2">🏆</span> Category Performance
                  </h3>
                  {renderCategoryPerformance()}
                </div>
              </div>
            )}
            
            {/* Visitors Tab */}
            {activeTab === "visitors" && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Visitors by District</h3>
                  {renderVisitorsBarChart()}
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Visitor Growth Trends</h3>
                  <div className="h-64 flex items-center justify-center text-gray-500">
                    Visitor growth chart visualization
                  </div>
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100 lg:col-span-2">
                  <h3 className="font-bold text-lg mb-4">Peak Visiting Seasons</h3>
                  <div className="h-64 flex items-center justify-center text-gray-500">
                    Seasonal trends visualization
                  </div>
                </div>
              </div>
            )}
            
            {/* Revenue Tab */}
            {activeTab === "revenue" && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Revenue Trends</h3>
                  {renderRevenueChart()}
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Revenue by Category</h3>
                  <div className="h-64 flex items-center justify-center text-gray-500">
                    Revenue category chart visualization
                  </div>
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100 lg:col-span-2">
                  <h3 className="font-bold text-lg mb-4">Revenue Forecast</h3>
                  <div className="h-64 flex items-center justify-center text-gray-500">
                    Revenue forecasting visualization
                  </div>
                </div>
              </div>
            )}
            
            {/* Demographics Tab */}
            {activeTab === "demographics" && (
              <div className="grid grid-cols-1 gap-6">
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Visitor Demographics</h3>
                  {renderDemographicCharts()}
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Geographic Distribution</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Geographic distribution map visualization
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Travel Party Size</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Travel party size chart visualization
                    </div>
                  </div>
                </div>
              </div>
            )}
            
            {/* Geospatial Tab */}
            {activeTab === "geospatial" && (
              <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                <h3 className="font-bold text-lg mb-4">Visitor Geographic Distribution</h3>
                <div className="flex mb-4 flex-wrap">
                  <div className="bg-blue-100 text-blue-800 px-3 py-1 rounded-lg text-sm mr-2 mb-2">
                    Heatmap: Visitor Density
                  </div>
                  <div className="bg-green-100 text-green-800 px-3 py-1 rounded-lg text-sm mr-2 mb-2">
                    Markers: Popular Locations
                  </div>
                  {userLocation && (
                    <div className="bg-purple-100 text-purple-800 px-3 py-1 rounded-lg text-sm mb-2">
                      Your Location
                    </div>
                  )}
                </div>
                <div ref={mapRef} className="h-96 rounded-lg z-0 w-full"></div>
                <div className="mt-4 text-sm text-gray-600">
                  {userLocation ? (
                    <p>Your location is being used to provide personalized insights</p>
                  ) : (
                    <p>Enable location services for personalized recommendations</p>
                  )}
                </div>
              </div>
            )}
            
            {/* Real-time Tab */}
            {activeTab === "realtime" && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100 lg:col-span-1">
                  <h3 className="font-bold text-lg mb-4">Current Visitors</h3>
                  {renderRealTimeVisitors()}
                </div>
                
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100 lg:col-span-2">
                  <h3 className="font-bold text-lg mb-4">Live Activity Map</h3>
                  <div className="h-96 rounded-lg bg-gray-100 flex items-center justify-center text-gray-500">
                    Live activity map visualization
                  </div>
                </div>
              </div>
            )}
            
            {/* Predictive Tab */}
            {activeTab === "predictive" && (
              <div className="space-y-6">
                {renderPredictiveInsights()}
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Demand Forecasting</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Demand forecasting visualization
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Optimal Pricing Model</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Pricing optimization visualization
                    </div>
                  </div>
                </div>
              </div>
            )}
            
            {/* Feedback Tab */}
            {activeTab === "feedback" && (
              <div className="grid grid-cols-1 gap-6">
                <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                  <h3 className="font-bold text-lg mb-4">Visitor Satisfaction</h3>
                  <div className="h-64 flex items-center justify-center text-gray-500">
                    Satisfaction metrics visualization
                  </div>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Top Positive Feedback</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Positive feedback word cloud visualization
                    </div>
                  </div>
                  
                  <div className="bg-white p-6 rounded-lg shadow border border-gray-100">
                    <h3 className="font-bold text-lg mb-4">Improvement Areas</h3>
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      Improvement areas chart visualization
                    </div>
                  </div>
                </div>
              </div>
            )}
            
            {/* Data refresh information */}
            <div className="text-center text-sm text-gray-500 mt-8">
              {mode === "demo" ? (
                <p>Showing demo data. Last simulated refresh: {new Date().toLocaleTimeString()}</p>
              ) : (
                <p>Live data from Power BI. Last refresh: {new Date().toLocaleTimeString()}</p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Analytics;
